SELECT CURRENT_TIMESTAMP(6)
FROM workflow
WHERE workspace_id = #{workspaceId} AND id = #{workflowId}

SELECT 
FROM workflow_date_enrollment
WHERE workspace_id = #{workspaceId}
  AND workflow_id = #{workflowId}
  AND record_type = 'deal'
  AND record_id = #{recordId}
  AND date_field = #{dateField}
  AND source_date = #{sourceDate}
FOR UPDATE

SELECT 
FROM workflow_date_enrollment
WHERE workspace_id = #{workspaceId}
  AND workflow_id = #{workflowId}
  AND record_type = 'deal'
  AND record_id = #{recordId}
  AND state IN ('planned', 'queued')
ORDER BY id
FOR UPDATE

mapper.update:
UPDATE workflow_date_enrollment
SET state = 'superseded', resolved_at = #{resolvedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND state = 'planned'

UPDATE workflow_date_enrollment
SET workflow_version_id = #{workflowVersionId},
    workflow_runtime_generation = #{workflowRuntimeGeneration},
    scheduled_local_date = #{scheduledLocalDate},
    due_at = #{dueAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND state = 'planned'

UPDATE workflow_date_enrollment
SET state = 'missed', resolved_at = #{resolvedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND state = 'planned'

UPDATE workflow_date_enrollment
SET state = 'queued', queued_at = #{queuedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND state = 'planned'

UPDATE workflow_date_enrollment
SET state = 'enrolled', workflow_run_id = #{workflowRunId}, resolved_at = #{resolvedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND state = 'queued'

UPDATE workflow_date_enrollment
SET state = 'planned', queued_at = NULL
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND state = 'queued'
  AND workflow_run_id IS NULL

UPDATE workflow_date_enrollment
SET state = 'missed', resolved_at = #{resolvedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND state = 'queued'
  AND workflow_run_id IS NULL

UPDATE workflow_date_enrollment
SET state = 'missed', resolved_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND state = 'queued'
  AND workflow_run_id IS NULL
